package com.distributor.erp.common.outbox;

import com.distributor.erp.common.tenant.TenantContext;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.Objects;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * Service invoked within active domain transactions to persist outbox records
 * for reliable eventual publication across modular boundaries (ADR04).
 */
@Service
public class OutboxPublisher {

    private static final Logger log = LoggerFactory.getLogger(OutboxPublisher.class);
    private static final UUID DEFAULT_SYSTEM_TENANT = UUID.fromString("00000000-0000-0000-0000-000000000001");

    private final OutboxRepository outboxRepository;
    private final ObjectMapper objectMapper;

    public OutboxPublisher(OutboxRepository outboxRepository, ObjectMapper objectMapper) {
        this.outboxRepository = outboxRepository;
        this.objectMapper = objectMapper;
    }

    /**
     * Publishes an event within the current business transaction using the convention:
     * publish(eventType, aggregateId, payload).
     *
     * @param eventType   the event type name (e.g., UserRegisteredEvent)
     * @param aggregateId the UUID of the aggregate root
     * @param payload     the event payload object to be serialized to JSON
     */
    @Transactional(propagation = Propagation.MANDATORY)
    public void publish(String eventType, UUID aggregateId, Object payload) {
        Objects.requireNonNull(aggregateId, "aggregateId must not be null");
        publish(eventType, aggregateId.toString(), payload);
    }

    /**
     * Publishes an event within the current business transaction.
     *
     * @param eventType   the event type name
     * @param aggregateId the string identifier of the aggregate root
     * @param payload     the event payload object
     */
    @Transactional(propagation = Propagation.MANDATORY)
    public void publish(String eventType, String aggregateId, Object payload) {
        String aggregateType = resolveAggregateType(eventType);
        publish(aggregateType, aggregateId, eventType, payload);
    }

    /**
     * Publishes an event with explicit aggregate type, aggregate ID, and event type.
     *
     * @param aggregateType the aggregate classification name
     * @param aggregateId   the identifier of the aggregate root
     * @param eventType     the domain event descriptor
     * @param payload       the event payload object
     */
    @Transactional(propagation = Propagation.MANDATORY)
    public void publish(String aggregateType, String aggregateId, String eventType, Object payload) {
        UUID tenantId = TenantContext.getTenantId();
        if (tenantId == null) {
            tenantId = DEFAULT_SYSTEM_TENANT;
        }
        publish(tenantId, aggregateType, aggregateId, eventType, payload);
    }

    /**
     * Publishes an event with explicit tenant context.
     *
     * @param tenantId      the tenant identifier
     * @param aggregateType the aggregate classification name
     * @param aggregateId   the identifier of the aggregate root
     * @param eventType     the domain event descriptor
     * @param payload       the event payload object
     */
    @Transactional(propagation = Propagation.MANDATORY)
    public void publish(UUID tenantId, String aggregateType, String aggregateId, String eventType, Object payload) {
        Objects.requireNonNull(tenantId, "tenantId must not be null");
        Objects.requireNonNull(aggregateType, "aggregateType must not be null");
        Objects.requireNonNull(aggregateId, "aggregateId must not be null");
        Objects.requireNonNull(eventType, "eventType must not be null");
        Objects.requireNonNull(payload, "payload must not be null");

        String jsonPayload = serializePayload(payload);
        OutboxEntity entity = new OutboxEntity(tenantId, aggregateType, aggregateId, eventType, jsonPayload);
        outboxRepository.save(entity);

        log.debug("Outbox event registered: type={}, aggregateId={}, tenantId={}", eventType, aggregateId, tenantId);
    }

    private String serializePayload(Object payload) {
        if (payload instanceof String stringPayload) {
            return stringPayload;
        }
        try {
            return objectMapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Failed to serialize outbox event payload to JSON", e);
        }
    }

    private String resolveAggregateType(String eventType) {
        if (eventType == null || eventType.isBlank()) {
            return "General";
        }
        if (eventType.endsWith("Event")) {
            return eventType.substring(0, eventType.length() - 5);
        }
        return eventType;
    }
}

package com.distributor.erp.common.outbox;

import java.time.Instant;
import java.util.List;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.data.domain.PageRequest;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * Scheduled worker processing pending outbox entries and publishing them
 * via Spring ApplicationEventPublisher (ADR04).
 */
@Service
public class OutboxProcessorService {

    private static final Logger log = LoggerFactory.getLogger(OutboxProcessorService.class);
    private static final int BATCH_SIZE = 50;
    private static final int MAX_RETRIES = 5;

    private final OutboxRepository outboxRepository;
    private final ApplicationEventPublisher applicationEventPublisher;

    public OutboxProcessorService(
            OutboxRepository outboxRepository,
            ApplicationEventPublisher applicationEventPublisher
    ) {
        this.outboxRepository = outboxRepository;
        this.applicationEventPublisher = applicationEventPublisher;
    }

    /**
     * Record representing a dispatched outbox domain event sent to listeners.
     */
    public record OutboxDomainEvent(
            UUID outboxId,
            UUID tenantId,
            String aggregateType,
            String aggregateId,
            String eventType,
            String payload,
            Instant createdAt
    ) {}

    /**
     * Polls and dispatches pending outbox events every 2 seconds with a fixed delay.
     */
    @Scheduled(fixedDelay = 2000, initialDelay = 5000)
    public void processPendingEvents() {
        List<OutboxEntity> pendingEvents = outboxRepository.findByStatusOrderByCreatedAtAsc(
                OutboxEntity.STATUS_PENDING,
                PageRequest.of(0, BATCH_SIZE)
        );

        if (pendingEvents.isEmpty()) {
            return;
        }

        log.debug("Found {} pending outbox events to dispatch", pendingEvents.size());
        for (OutboxEntity event : pendingEvents) {
            dispatchSingleEvent(event.getId());
        }
    }

    /**
     * Retries previously failed outbox events that have not exceeded MAX_RETRIES.
     */
    @Scheduled(fixedDelay = 15000, initialDelay = 10000)
    public void retryFailedEvents() {
        List<OutboxEntity> failedEvents = outboxRepository.findRetryableFailedEvents(
                MAX_RETRIES,
                PageRequest.of(0, BATCH_SIZE)
        );

        if (failedEvents.isEmpty()) {
            return;
        }

        log.info("Found {} failed outbox events eligible for retry", failedEvents.size());
        for (OutboxEntity event : failedEvents) {
            dispatchSingleEvent(event.getId());
        }
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void dispatchSingleEvent(UUID eventId) {
        OutboxEntity entity = outboxRepository.findById(eventId).orElse(null);
        if (entity == null || OutboxEntity.STATUS_PROCESSED.equals(entity.getStatus())) {
            return;
        }

        try {
            OutboxDomainEvent domainEvent = new OutboxDomainEvent(
                    entity.getId(),
                    entity.getTenantId(),
                    entity.getAggregateType(),
                    entity.getAggregateId(),
                    entity.getEventType(),
                    entity.getPayload(),
                    entity.getCreatedAt()
            );

            applicationEventPublisher.publishEvent(domainEvent);
            entity.markProcessed();
            outboxRepository.save(entity);
            log.debug("Successfully published and acknowledged outbox event {}", eventId);
        } catch (Exception ex) {
            log.error("Failed to publish outbox event {}: {}", eventId, ex.getMessage(), ex);
            entity.markFailed(ex.getMessage());
            outboxRepository.save(entity);
        }
    }
}

package com.distributor.erp;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.scheduling.annotation.EnableScheduling;

/**
 * Spring Boot main entrypoint class bootstrapping the modular monolith.
 */
@SpringBootApplication
@EnableScheduling
public class ErpApplication {

    public static void main(String[] args) {
        SpringApplication.run(ErpApplication.class, args);
    }
}
